  "status": "TUNED-20261104-AUTO",
  "status_note": "Weights chosen autonomously per Ben's 2026-11-04 directive item 7 (normalize, bounded sensitivity checks, documented choice; no pause for approval). Every term and weight is re-read by fr_objective at every solve; this file is the only place weights live. Rationale per term in weight_sensitivity log + README. Any weight here can be replaced by Ben at any time; the re-solve is checkpoint-based.",
  "read_at": "solve time (fresh jsondecode in fr_objective)",
  "terms": [
    {
      "name": "torque_capacity_deficit",
      "class": "primary_capacity",
      "weight": 100.0,
      "normalization": "sum_tau_target_abs (sum over the pose grid of |tau_target|)",
      "definition": "sum over pose grid of max(0, |tau_target| - |tau_primary|), i.e. the SIGNED meet-or-beat deficit on the group's primary dof torque, per master item 8 (torque capacity primary). With signed per-pose targets from targets_v2, tau_target varies per pose.",
      "sign_convention": "tau_primary and tau_target are signed about the same axis; deficit uses absolute magnitudes of the same sign convention (flexion targets met by flexion torque)"
    },
    {
      "name": "usable_rom_shortfall",
      "class": "primary_rom",
      "weight": 40.0,
      "normalization": "grid size (fraction of poses, so the term lives in [0,1])",
      "definition": "fraction of pose-grid cells where |tau_primary| < |tau_target| (usable motion range primary, master item 8); report-only companion: fraction of cells feasible"
    },
    {
      "name": "torque_shape",
      "class": "shape",
      "weight": 0.5,
      "normalization": "mean over grid of (tau_primary - tau_target)^2 / mean(tau_target.^2)",
      "definition": "small, explicitly weighted torque-shape penalty (master item 8): squared residual to the SIGNED target curve. Defined SEPARATELY from the capacity terms; its small weight guarantees it cannot remove the deficit incentive. Never an off-axis torque term.",
      "sensitivity": "±2x perturbation leaves the chosen designs unchanged within solver noise (weight_sensitivity log)"
    },
    {
      "name": "bpa_bpa_overlap_soft",
      "class": "soft_penalty",
      "weight": 2.0,
      "normalization": "sleeve inflated diameter at rest per pose (depth reported in mm as well)",
      "definition": "soft BPA-BPA interference (handoff item 9 / master item 8): summed overlap depth between the group's OWN parallel BPA sleeves from the pose-dependent inflated envelopes, physically simultaneous poses only. Depth and extent reported per pose."
    },
    {
      "name": "retained_bpa_corridor_soft",
      "class": "soft_penalty",
      "weight": 2.0,
      "normalization": "sleeve inflated diameter at rest per pose (extent reported in mm as well)",
      "definition": "v2 (Ben 2026-11-04): soft interference against RETAINED INNER-LAYER BPA sleeve corridors (fr_envelope kind 'bpa_sleeve'/'bpa_end'), evaluated at physically simultaneous poses. Depth/extent recorded every evaluation. An outer-layer BPA is never INFEASIBLE for crossing an inner layer's sleeve corridor - it pays this penalty; rigid fittings and tackle blocks of inner layers stay HARD (retained_rigid_envelopes).",
      "added_by": "Ben's 2026-11-04 directive item 6"
    }
  ],
  "forbidden": [
    "off_axis_torque_penalty in ANY form, including inherited regularizers disguised as another term (master item 8; handoff item 9). Secondary joint torques are RECORDED in the evaluation report and never penalized.",
    "any hard universal muscle-to-muscle clearance constraint (BPA-BPA overlap is soft; only rigid hardware/bone and the z=0 centerline are hard)",
    "enforcing inner-layer BPA SLEEVE corridors as a HARD clearance constraint (Ben 2026-11-04: that was the stage-1 layering demo's unintended hard BPA-BPA constraint; rigid fittings/tackle of inner layers remain hard)"
  ],
  "hard_constraints": [
    {
      "name": "centerline_z0",
      "definition": "sideSign * z_pelvis >= 0 for EVERY candidate attachment point and mechanical mount anchor, transformed into the pelvis frame at EVERY evaluated pose (handoff item 8, verbatim). sideSign = +1 (right side of record). Sign flips / absolute values forbidden. Tolerance 1e-4 m, stated per evaluation in rep.cinfo.",
